use system.os
use system.fs
use system.process
use system.gpu.atomic
use system.collections.array
use system.collections.list

const MAX_COUNT = 4000000
const MAX_BINS = 256

fn fail(message String)
    eprintln(message)
    exit(1)

// Splits the input line on any whitespace and returns the non-empty fields.
fn fields(text String) List<String>
    let flat = text.replace("\r", " ").replace("\n", " ").replace("\t", " ")
    var out = List<String>()
    for part in flat.split(" ")
        if not part.is_empty(): out.push(part)
    out

fn parse_field(text String, name String, low int, high int) int
    match text.to_int()
        Some(v) if v >= low and v <= high: v
        Some(_) | None:
            fail(f"invalid {name}: {text}")
            0

fn main() int
    let args = Args()
    if args.length() < 1: fail("usage: main <input-file>")
    let fs = Fs()
    var text = ""
    match fs.read_file(args.element_at(0))
        Result.Ok(t): text = t
        Result.Err: fail("cannot read input file")
    let parts = fields(text)
    if parts.length() < 3: fail("input must hold: <count> <seed> <bins>")
    let count = parse_field(parts.element_at(0), "count", 0, MAX_COUNT)
    let seed = parse_field(parts.element_at(1), "seed", 0, 9999)
    let bins = parse_field(parts.element_at(2), "bins", 1, MAX_BINS)

    gpu var values = Array<int, MAX_COUNT>()
    gpu var hist = Array<Atomic<i32>, MAX_BINS>()
    gpu var counts = Array<int, MAX_BINS>()

    // Kernel 1: generate the values.
    forall i in 0..count
        let a = ((i % 40000) * 1597 + seed + 51749) % 40000
        let b = (a * a + a * 37 + 11) % 40009
        let c = (b * 613 + 7919) % 40009
        let d = (c + (i / 40000) * 7919) % 40009
        values[i] = d % 1000

    // Kernel 2: count them into bins.
    forall i in 0..count
        atomic_add(hist, values[i] * bins / 1000, 1)

    // Kernel 3: copy the atomic counters into a plain buffer for readback.
    forall k in 0..MAX_BINS
        counts[k] = atomic_add(hist, k, 0)

    var host = Array<int, MAX_BINS>()
    host = counts
    for k in 0..bins
        println(f"BIN {k} {host[k]}")
    println(f"TOTAL {count}")
    0

